def assemble_and_save():
    os.makedirs(PROCESSED_DIR, exist_ok=True)

    # 1. Human Native Pool
    all_human_native = []
    for text, domain, tag in HUMAN_TEXTS:
        all_human_native.append({
            "text": text,
            "label": "human",
            "class_id": 0,
            "domain": domain,
            "generator": "human_native",
            "word_count": len(text.split()),
            "tag": tag
        })

    # 2. Human ESL Pool
    all_human_esl = []
    for text, domain, tag in ESL_TEXTS:
        all_human_esl.append({
            "text": text,
            "label": "human",
            "class_id": 0,
            "domain": domain,
            "generator": "human_esl",
            "word_count": len(text.split()),
            "tag": tag
        })

    combined_human = all_human_native + all_human_esl

    # 3. Human-Refined Pool (each human text polished by LLM)
    all_human_refined = []
    for h in combined_human:
        polished = polish_human_text_to_refined(h["text"])
        all_human_refined.append({
            "text": polished,
            "label": "human_ai_refined",
            "class_id": 1,
            "domain": h["domain"],
            "generator": "human_polished_by_llm",
            "word_count": len(polished.split()),
            "tag": f"refined_{h['tag']}"
        })

    # 4. AI In-Distribution Pool
    all_ai = []
    for text, model, domain, tag in AI_IN_DIST_TEXTS:
        all_ai.append({
            "text": text,
            "label": "ai_generated",
            "class_id": 3,
            "domain": domain,
            "generator": model,
            "word_count": len(text.split()),
            "tag": tag
        })

    # Duplicate AI in-dist with slight prompt extensions to balance human count
    extended_ai = all_ai.copy()
    for a in all_ai:
        extended_ai.append({
            "text": a["text"],
            "label": "ai_generated",
            "class_id": 3,
            "domain": a["domain"],
            "generator": a["generator"],
            "word_count": a["word_count"],
            "tag": f"{a['tag']}_ext"
        })
    extended_ai = extended_ai[:len(combined_human)]

    # 5. AI-Refined Pool (each AI text paraphrased)
    all_ai_refined = []
    for a in extended_ai:
        para = paraphrase_ai_text_to_refined(a["text"])
        all_ai_refined.append({
            "text": para,
            "label": "ai_ai_refined",
            "class_id": 2,
            "domain": a["domain"],
            "generator": f"paraphrased_{a['generator']}",
            "word_count": len(para.split()),
            "tag": f"paraphrased_{a['tag']}"
        })

    # 6. Unseen Models
    qwen_records = []
    for text, model, tag in QWEN_UNSEEN_TEXTS:
        qwen_records.append({
            "text": text,
            "label": "ai_generated",
            "class_id": 3,
            "domain": "technical",
            "generator": model,
            "word_count": len(text.split()),
            "tag": tag
        })

    deepseek_records = []
    for text, model, tag in DEEPSEEK_UNSEEN_TEXTS:
        deepseek_records.append({
            "text": text,
            "label": "ai_generated",
            "class_id": 3,
            "domain": "academic",
            "generator": model,
            "word_count": len(text.split()),
            "tag": tag
        })

    # Paraphrased Test pool
    para_test = []
    for x in qwen_records + deepseek_records:
        p = paraphrase_ai_text_to_refined(x["text"])
        para_test.append({
            "text": p,
            "label": "ai_ai_refined",
            "class_id": 2,
            "domain": x["domain"],
            "generator": f"paraphrased_{x['generator']}",
            "word_count": len(p.split()),
            "tag": f"para_test_{x['tag']}"
        })

    # Partition into Train (60%), Val (20%), Test (20%)
    train_records = []
    val_records = []
    test_indist_records = []

    def split_pool(pool: List[Dict[str, Any]], tr_pct=0.60, val_pct=0.20):
        pool_copy = pool.copy()
        random.seed(SEED)
        random.shuffle(pool_copy)
        n = len(pool_copy)
        n_tr = int(n * tr_pct)
        n_val = int(n * val_pct)
        return pool_copy[:n_tr], pool_copy[n_tr:n_tr + n_val], pool_copy[n_tr + n_val:]

    for p in [combined_human, all_human_refined, all_ai_refined, extended_ai]:
        tr, v, ts = split_pool(p)
        train_records.extend(tr)
        val_records.extend(v)
        test_indist_records.extend(ts)

    random.seed(SEED)
    random.shuffle(train_records)
    random.shuffle(val_records)
    random.shuffle(test_indist_records)

    splits = {
        "train": train_records,
        "val": val_records,
        "test_indist": test_indist_records,
        "test_unseen_qwen": qwen_records,
        "test_unseen_deepseek": deepseek_records,
        "test_esl": all_human_esl,
        "test_paraphrased": para_test + [x for x in test_indist_records if x["class_id"] == 2]
    }

    for name, data in splits.items():
        fp = os.path.join(PROCESSED_DIR, f"{name}.jsonl")
        with open(fp, "w", encoding="utf-8") as f:
            for item in data:
                f.write(json.dumps(item, ensure_ascii=False) + "\n")
        print(f"[Dataset] Wrote {len(data):3d} samples -> {fp}")

    # Build 30-sample manual comparison sheet
    samples = []
    # 6 Human Native
    for h in all_human_native[:6]:
        samples.append({
            "id": f"QB-{len(samples)+1:02d}",
            "text": h["text"],
            "expected_class": "Human-written",
            "class_id": 0,
            "type": "human_native",
            "domain": h["domain"],
            "word_count": h["word_count"],
            "notes": "Authentic human author prose with domain scholarship or personal narrative."
        })
    # 4 Human ESL
    for e in all_human_esl[:4]:
        samples.append({
            "id": f"QB-{len(samples)+1:02d}",
            "text": e["text"],
            "expected_class": "Human-written",
            "class_id": 0,
            "type": "human_esl",
            "domain": e["domain"],
            "word_count": e["word_count"],
            "notes": "Authentic non-native English essay testing detector false-positive rate."
        })
    # 6 Human-Refined
    for hr in all_human_refined[:6]:
        samples.append({
            "id": f"QB-{len(samples)+1:02d}",
            "text": hr["text"],
            "expected_class": "Human-written & AI-refined",
            "class_id": 1,
            "type": "human_ai_refined",
            "domain": hr["domain"],
            "word_count": hr["word_count"],
            "notes": "Human prose polished and regularized by an LLM line editor."
        })
    # 6 AI-Refined
    for ar in all_ai_refined[:6]:
        samples.append({
            "id": f"QB-{len(samples)+1:02d}",
            "text": ar["text"],
            "expected_class": "AI-generated & AI-refined",
            "class_id": 2,
            "type": "ai_ai_refined",
            "domain": ar["domain"],
            "word_count": ar["word_count"],
            "notes": "AI text passed through syntactic restructuring and automated paraphrasing."
        })
    # 8 Pure AI (GPT-4o, Claude 3.5, Gemini 1.5, Llama 3.3, Qwen 2.5, DeepSeek-V3)
    for ai in all_ai[:4]:
        samples.append({
            "id": f"QB-{len(samples)+1:02d}",
            "text": ai["text"],
            "expected_class": "AI-generated",
            "class_id": 3,
            "type": f"ai_pure_{ai['generator']}",
            "domain": ai["domain"],
            "word_count": ai["word_count"],
            "notes": f"Direct generation from {ai['generator']} without subsequent modification."
        })
    for q in qwen_records[:2]:
        samples.append({
            "id": f"QB-{len(samples)+1:02d}",
            "text": q["text"],
            "expected_class": "AI-generated",
            "class_id": 3,
            "type": "ai_pure_qwen",
            "domain": q["domain"],
            "word_count": q["word_count"],
            "notes": "Unseen open frontier model: Qwen-2.5-72B."
        })
    for d in deepseek_records[:2]:
        samples.append({
            "id": f"QB-{len(samples)+1:02d}",
            "text": d["text"],
            "expected_class": "AI-generated",
            "class_id": 3,
            "type": "ai_pure_deepseek",
            "domain": d["domain"],
            "word_count": d["word_count"],
            "notes": "Unseen frontier model: DeepSeek-V3."
        })

    samples = samples[:30]
    json_path = os.path.join(DATA_DIR, "quillbot_comparison_sheet.json")
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(samples, f, indent=2, ensure_ascii=False)

    md_path = os.path.join(DATA_DIR, "quillbot_comparison_sheet.md")
    with open(md_path, "w", encoding="utf-8") as f:
        f.write("# QuillBot AI Detector Hand-Verification Benchmark (30 Samples)\n\n")
        f.write("This sheet provides exactly 30 standardized test passages across all 4 target classes for manual evaluation against QuillBot's AI Detector without violating rate limits or ToS.\n\n")
        f.write("| ID | Target Expected Class | Type / Sub-Genre | Words | First 80 Chars | QuillBot Verdict (Manual) | Veritas Verdict | Match? |\n")
        f.write("|---|---|---|---|---|---|---|---|\n")
        for s in samples:
            preview = s["text"][:75].replace("\n", " ").replace("|", " ") + "..."
            f.write(f"| {s['id']} | **{s['expected_class']}** | `{s['type']}` | {s['word_count']} | {preview} | *(Pending)* | *(Pending)* | - |\n")
        f.write("\n\n---\n\n## Complete Sample Texts\n\n")
        for s in samples:
            f.write(f"### Sample {s['id']} — [{s['expected_class']}]\n")
            f.write(f"- **Type**: `{s['type']}` | **Domain**: `{s['domain']}` | **Word Count**: {s['word_count']}\n")
            f.write(f"- **Rationale**: {s['notes']}\n\n")
            f.write("```text\n")
            f.write(s["text"] + "\n")
            f.write("```\n\n")

    print(f"[Comparison] Built 30-sample manual comparison sheet -> {json_path} & {md_path}")


if __name__ == "__main__":
    assemble_and_save()
